SELECT location, CASE WHEN dept_name IN ('Sales', 'Finance') THEN 'priority' ELSE 'other' END AS dept_name_group, SUM(budget) AS total_budget, COUNT(CASE WHEN location = 'New York' THEN 1 END) AS new_york_count, SUM(CASE WHEN dept_name = 'Finance' THEN 1 ELSE 0 END) AS finance_count FROM departments WHERE budget >= 1447000 GROUP BY location, dept_name_group HAVING COUNT(CASE WHEN location = 'New York' THEN 1 END) > 4
